struct EntityState {
      paint: Paint,
      transform: State,
      material: Material,
  };

  @group(2) @binding(0) var<storage, read> states: array<EntityState>;

export function packInstanceIndex(stateIndex: number, localIndex: number = 0, isMega: boolean = false): number {
      if (isMega || localIndex > 16383) {
          // Mega-Instance Mode: MSB = 1, 13-bit state (0..8,191), 18-bit local (0..262,143)
          return (0x80000000 | ((stateIndex & 0x1FFF) << 18) | (localIndex & 0x3FFFF)) >>> 0;
      }
      // Standard Mode: MSB = 0, 18-bit state (0..262,144), 14-bit local (0..16,383)
      return (((stateIndex & 0x3FFFF) << 14) | (localIndex & 0x3FFF)) >>> 0;
  }

fn getStateIndex(instance_index: u32) -> u32 {
      let is_mega = (instance_index & 0x80000000u) != 0u;
      return select(instance_index >> 14u, (instance_index >> 18u) & 0x1FFFu, is_mega);
  }

  fn getLocalIndex(instance_index: u32) -> u32 {
      let is_mega = (instance_index & 0x80000000u) != 0u;
      return select(instance_index & 0x3FFFu, instance_index & 0x3FFFFu, is_mega);
  }
